import XCTest
final class EditorUITests:XCTestCase {
    func testEditingAndExportControls(){let app=XCUIApplication();app.launchArguments=["--uitesting"];app.launch();XCTAssertTrue(app.images["photoCanvas"].waitForExistence(timeout:20));let enhance=app.buttons["enhance"];XCTAssertTrue(enhance.waitForExistence(timeout:10));enhance.tap();let undo=app.buttons["undo"];let enabled=NSPredicate(format:"enabled == true");expectation(for:enabled,evaluatedWith:undo);waitForExpectations(timeout:30);undo.tap();app.buttons["compare"].tap();app.buttons["compare"].tap();app.buttons["tab-Кадр"].tap();app.buttons["crop"].tap();expectation(for:enabled,evaluatedWith:undo);waitForExpectations(timeout:20);undo.tap();app.buttons["tab-Свет"].tap();XCTAssertTrue(app.buttons["applyAdjustments"].exists);app.buttons["applyAdjustments"].tap();expectation(for:enabled,evaluatedWith:app.buttons["saveMenu"]);waitForExpectations(timeout:20);app.buttons["saveMenu"].tap();XCTAssertTrue(app.buttons["Сохранить в Фото"].waitForExistence(timeout:5));let shot=XCTAttachment(screenshot:app.screenshot());shot.name="Editor-and-export";shot.lifetime = .keepAlways;add(shot)}
    func testModelsPanel(){let app=XCUIApplication();app.launchArguments=["--uitesting"];app.launch();XCTAssertTrue(app.images["photoCanvas"].waitForExistence(timeout:20));app.swipeUp();let button=app.buttons["ИИ-модели и качество"];XCTAssertTrue(button.waitForExistence(timeout:5));button.tap();XCTAssertTrue(app.navigationBars["Модели"].waitForExistence(timeout:5));let shot=XCTAttachment(screenshot:app.screenshot());shot.name="Models";shot.lifetime = .keepAlways;add(shot)}
}
